import{z as s,x as A,o as e,c as p,q as E,j as B,D as t,d as l,s as o,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"BitFit","description":"","frontmatter":{"title":"BitFit","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bitfit.md","filePath":"llm/bitfit.md","lastUpdated":1791063341000}'),F={name:"llm/bitfit.md"};function d(m,a,f,b,h,C){const r=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=E('<h1 id="bitfit" tabindex="-1">BitFit <a class="header-anchor" href="#bitfit" aria-label="Permalink to &quot;BitFit&quot;">​</a></h1><div class="epigraph"><p>只更新偏置项，可训练参数小到可以忽略，却仍能在不少分类式适应上移动决策面；它改的是每层的偏移，不是子空间。</p><footer>—— Ben Zaken、Goldberg、Ravfogel，BitFit: Simple Parameter-efficient Fine-tuning for Transformer，ACL 2022</footer></div><p><a href="/llm/relora">ReLoRA</a> 仍在玩矩阵增量。<a href="/llm/lora">LoRA</a> / VeRA 也是。BitFit 把问题拧到另一端：Transformer 里的偏置 \\(b\\) 本来几乎不被讨论，却是每层仿射 \\(Wx+b\\) 的平移。Ben Zaken 等人 2022 年表明，冻结 \\(W\\)、只训 \\(b\\)（及可选的任务头），在若干 GLUE 式任务上可接近全参。本课的缺口是：指令生成是否还买账；以及偏置适应在解码器 LLM 上能走多远。不把前缀调参（<a href="/llm/p-tuning-v2">下一课 P-tuning v2</a>）写成「也是只训一点点」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>适配器与 LoRA 引入新矩阵，改变或旁路计算图。若适应只需要把已有特征的阈值挪一挪——情感、蕴含、是否拒答——平移激活可能够用。偏置恰好是按通道的平移。问题：生成式 SFT 要改的是整段条件分布，不是单一 logit 阈值。只动 \\(b\\)，表达力是否够把<a href="/llm/instruction-data-lineage">谱系</a>里的助手口吻写进去？</p><p><span class="marginnote">术语翻译：偏置 \\(b\\) 就是每层输出统一加的一个「底数」向量：\\(y=Wx+b\\)。它不随输入变，像每个通道话筒的零点旋钮；BitFit 做的就是只拧这些零点，一根放大线路（\\(W\\)）都不动。</span></p><p>第二条：许多 LLM 实现把偏置从线性层拿掉（Llama 风格），BitFit 无对象可训，只能动 LayerNorm 的 \\(\\beta\\)、或词表偏置。配方必须先清点「哪些 \\(b\\) 存在」。</p><h3 id="偏置不是低秩矩阵的特例" tabindex="-1">偏置不是低秩矩阵的特例 <a class="header-anchor" href="#偏置不是低秩矩阵的特例" aria-label="Permalink to &quot;偏置不是低秩矩阵的特例&quot;">​</a></h3><p>LoRA 的 \\(r=1\\) 仍在改 \\(W\\) 的一个方向。BitFit 完全不改 \\(W\\) 的列空间，只加与输入无关的向量。不能把 BitFit 当成 \\(r=0\\) 的 LoRA。几何不同，失败模式也不同：特征方向错了，平移救不了。</p><p><span class="marginnote">原文实验以编码器分类为主。迁移到解码器指令微调时，应当作弱基线：先看格式能否学会，再谈知识。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冻结所有 \\(W\\) 与嵌入（除非任务加了新特殊 token），打开：注意力与 FFN 线性层的 bias（若有）、LayerNorm/RMSNorm 的仿射、LM head 的 bias（若有）。学习率可大于全参——参数极少——但仍远小于会打爆范数的值；按<a href="/llm/lora-vs-full-lr">适配器侧</a>的「大胆、但监控源域」来扫。SFT 用<a href="/llm/response-only-loss">仅回复</a>与同一<a href="/llm/chat-template">模板</a>。</p>',12)),(e(),B(n,null,{default:t(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20W%5B%22%E5%86%BB%E7%BB%93%20W%22%5D%0A%20%20W%20--%3E%20B%5B%22%E5%8F%AF%E8%AE%AD%E7%BB%83%20b%22%5D%0A%20%20B%20--%3E%20Y%5B%22Wx%20%2B%20b%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("p",null,"若架构无 bias，BitFit 退化成「只训范数仿射」，能力更弱，应在报告里改名，不要冒充原文设定。可与 LoRA 比：同一数据上 BitFit 作为下限，LoRA \\(r=8\\) 作为常规。",-1)),a[4]||(a[4]=i("h2",{id:"机制",tabindex:"-1"},[l("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=i("p",null,"\\(y=Wx+b\\) 里，\\(b\\) 不随 token 变。它能改变每个通道的触发点，从而改变后续非线性的工作区，间接改变注意力分数的分布。这对于「把某类特征推过阈值」有效。它不能增加新的特征组合方向——那需要改 \\(W\\) 或加秩。指令遵循若主要是「看到特殊 token 后切换说话方式」，而该切换已在预训练特征里，偏置或许能放大；若需要新的工具 JSON 语法，通常不够。",-1)),(e(),B(n,null,{default:t(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%B8%8B%E6%B8%B8%E9%80%82%E5%BA%94%E8%A6%81%E5%81%9A%E4%BB%80%E4%B9%88%EF%BC%9F%22%5D%20--%3E%20TH%7B%22%E5%8F%AA%E6%8C%AA%E9%98%88%E5%80%BC%20%2F%20%E6%A0%A1%E5%87%86%EF%BC%9F%22%7D%0A%20%20TH%20--%3E%7C%22%E6%98%AF%22%7C%20BF%5B%22BitFit%EF%BC%9A%E5%8F%AA%E8%AE%AD%20b%EF%BC%8C%E5%8F%82%E6%95%B0%E7%BA%A6%200.1%25%22%5D%0A%20%20TH%20--%3E%7C%22%E8%A6%81%E6%96%B0%E7%89%B9%E5%BE%81%E6%96%B9%E5%90%91%22%7C%20LR%5B%22LoRA%EF%BC%9A%E4%BD%8E%E7%A7%A9%E7%9F%A9%E9%98%B5%E6%94%B9%20W%20%E7%9A%84%E6%96%B9%E5%90%91%22%5D%0A%20%20TH%20--%3E%7C%22%E8%A6%81%E6%96%B0%E6%A0%BC%E5%BC%8F%20%2F%20%E6%96%B0%E7%9F%A5%E8%AF%86%22%7C%20FT%5B%22%E5%85%A8%E5%8F%82%20SFT%22%5D%0A%20%20BF%20--%3E%20C1%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E6%9E%81%E5%B0%8F%EF%BC%8C%E9%81%97%E5%BF%98%E6%9C%80%E5%B0%91%22%5D%0A%20%20LR%20--%3E%20C2%5B%22%E5%B8%B8%E8%A7%84%E9%BB%98%E8%AE%A4%22%5D%0A%20%20FT%20--%3E%20C3%5B%22%E8%A1%A8%E8%BE%BE%E5%8A%9B%E6%9C%80%E9%AB%98%EF%BC%8C%E6%88%90%E6%9C%AC%E6%9C%80%E9%AB%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>这张图回答的问题是：按任务需要选适应手段——需要多大的改动，决定该开多大的旋钮；BitFit 是其中最小的那一档。</p><p>遗忘：几乎不动 \\(W\\)，源域特征保持最好，与 Biderman 等人对 LoRA 的「忘得少」同方向、更极端。学得也更少。</p><p><span class="marginnote">常见误区：以为 BitFit「几乎不更新所以最安全」。遗忘确实几乎为零，但代价是学得更少——它把「不忘」和「学会」混在一张成绩单里。下游需要新知识或新格式时，遗忘率再小也没意义，因为压根没学会。</span></p><p><span class="marginnote">NEFTune 动嵌入表示；BitFit 动偏置。二者可叠，但都是弱干预。脏数据上 BitFit 过拟合偏置，表现为所有回复加上固定腔调偏移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>生成任务、工具调用、领域术语内化，默认不要只靠 BitFit。分类、校准、轻度风格、作为消融基线，值得跑。服务期 BitFit 的检查点极小，可按用户存一份 \\(\\Delta b\\)，合并是向量加，无秩冲突——这比后课<a href="/llm/lora-merge-conflict">LoRA 合并</a>干净，前提是任务够简单。</p><p>无 bias 的 Llama 族上，优先 LoRA 而不是硬上 BitFit。P-tuning 走另一条「不改 \\(W\\)」：改前缀嵌入，下一课。</p><p><span class="marginnote">数字实例：BERT-base 量级上，BitFit 可训参数约占 0.1%（十万量级），全参是 1.1 亿——相差约千倍。放到几十 B 参数的现代模型上，全参微调一张卡都放不下，而一份 \\(\\Delta b\\) 检查点只有几 MB。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BitFit 只训偏置（及范数仿射），不改 \\(W\\) 的列空间。</li><li>对阈值型适应有效，对需要新方向的生成 SFT 通常不够。</li><li>许多解码器没有线性偏置，必须先清点参数。</li><li>遗忘极少、表达力天花板极低；适合当弱基线。</li><li>学习率按少量可训练参数取，仍须监控源域。</li><li>出处：Ben Zaken 等，BitFit，ACL 2022。</li></ul>',10))])}const c=s(F,[["render",d]]);export{T as __pageData,c as default};
